func_36.solution:
def retry(n):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for i in range(n):
                try:
                    return func(*args, **kwargs)
                except Exception:
                    if i == n - 1:
                        raise
        return wrapper
    return decorator

